import io
import unittest
from dotenv.parser import parse_stream

class ParserTests(unittest.TestCase):
    def test_values(self):
        rows=list(parse_stream(io.StringIO("export A=one # comment\nB='two words'\n")))
        self.assertEqual([(r.key,r.value,r.error) for r in rows],[('A','one',False),('B','two words',False)])
    def test_line_positions(self):
        rows=list(parse_stream(io.StringIO('A=1\rB=2\r\nC=3\nD=4')))
        self.assertEqual([r.original.line for r in rows],[1,2,3,4])
    def test_error_recovery(self):
        rows=list(parse_stream(io.StringIO('BAD="unterminated\nGOOD=value\n')))
        self.assertTrue(rows[0].error)
        self.assertEqual((rows[-1].key,rows[-1].value),('GOOD','value'))
if __name__=='__main__': unittest.main()

